--
-- Table structure for table `properties`
--

DROP TABLE IF EXISTS `properties`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `properties` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `area_id` int unsigned NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `sub_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `slug` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mandate_ref` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rera_number` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'DLRERA2023A00892',
  `property_type` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `listing_type` enum('sale','rent') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'sale',
  `price` decimal(15,2) NOT NULL DEFAULT '0.00',
  `price_display` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `property_size` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `plot_size` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bedrooms` int unsigned DEFAULT '0',
  `bathrooms` int unsigned DEFAULT '0',
  `parking_spaces` int unsigned DEFAULT '0',
  `floor_info` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `orientation` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ceiling_height` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `architect_info` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `property_location` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `google_map_url` text COLLATE utf8mb4_unicode_ci,
  `coordinates` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `description` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `provenance_quote` text COLLATE utf8mb4_unicode_ci,
  `lifestyle_quote` text COLLATE utf8mb4_unicode_ci,
  `featured_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_featured` tinyint(1) NOT NULL DEFAULT '0',
  `status` enum('published','draft','archived') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'published',
  `sort_order` int NOT NULL DEFAULT '0',
  `seo_title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `meta_description` text COLLATE utf8mb4_unicode_ci,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_properties_slug` (`slug`),
  KEY `idx_properties_status_type` (`status`,`listing_type`),
  KEY `idx_properties_featured` (`is_featured`,`status`),
  KEY `idx_properties_area` (`area_id`),
  CONSTRAINT `fk_properties_area` FOREIGN KEY (`area_id`) REFERENCES `areas` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

