INSERT INTO `properties` VALUES (1,1,'Modern Minimalist Villa with Lap Pool',NULL,'the-diplomatic-boulevard-villa-vasant-vihar','VV-VILLA-02','DLRERA2023A00892','Independent Luxury Bungalow','sale',350000000.00,'₹ 35.00 Cr','5,400 sq. ft.','600 sq. yds',5,6,5,'Ground + 2 Floors + Basement',NULL,NULL,NULL,'Vasant Vihar','https://maps.google.com/?q=Block+A+Vasant+Vihar+New+Delhi',NULL,'An architectural tour-de-force positioned along one of Vasant Vihar\'s widest and most private tree-canopied avenues. This standalone estate features soaring 13-foot ceilings, an expansive double-height grand living salon, a private heated indoor pool, an elevator serving all levels, and a landscaped rooftop lounge with panoramic tree-top views. Designed for generational living and diplomatic-scale hosting, the residence includes a fully appointed Italian modular show kitchen, secondary prep kitchen, and dedicated staff quarters for four attendants.',NULL,NULL,'/assets/images/stitch/area-prop-residence.jpg',0,'published',11,'Independent Luxury Villa for Sale in Vasant Vihar | Elite Homez','Exquisite 6 BHK independent bungalow on 800 sq. yds. in Vasant Vihar with private pool, elevator, and sprawling garden.','2026-09-12 12:09:52','2026-09-12 16:40:27'),(2,2,'Elegant Independent House',NULL,'the-heritage-park-residence-jor-bagh','EH-DEL-2','DLRERA2023A00892','Ground Floor with Basement & Garden','rent',290000000.00,'₹ 12.00 Lakh / Month','5,500 sq.ft.','575 Sq. Yds.',5,4,4,'Ground Floor + Finished Basement',NULL,NULL,NULL,'Jor Bagh','https://maps.google.com/?q=Jor+Bagh+New+Delhi',NULL,'Overlooking the serene green buffer of Lodi Gardens, this masterfully curated ground-floor residence combines heritage proportions with state-of-the-art contemporary interior architecture. Featuring an exclusive 1,800 sq. ft. private manicured lawn, floor-to-ceiling soundproof acoustic glazing, and an entertainment basement complete with a temperature-controlled wine cellar and personal cinema salon.',NULL,NULL,'/assets/images/properties/residence-jor-bagh.jpg',0,'published',12,'Luxury Garden Floor in Jor Bagh | Elite Homez','Exclusive 4 BHK ground floor residence with private lawn and entertainment basement in Jor Bagh, New Delhi.','2026-09-12 12:09:52','2026-09-12 14:55:25'),(3,3,'Premium Villa',NULL,'the-fairway-penthouse-golf-links','EH-DEL-3','DLRERA2023A00892','Duplex Penthouse with Private Terrace','sale',420000000.00,'₹ 25.00 Cr','8,000 sq.ft.','650 Sq. Yds.',6,6,4,'Third Floor + Private Terrace',NULL,NULL,NULL,'Golf Links','https://maps.google.com/?q=Golf+Links+New+Delhi',NULL,'An ultra-rare offering in Delhi\'s most exclusive residential address. This duplex penthouse commands uninterrupted fairway vistas across the lush canopy of the Delhi Golf Club. Boasting a private glass-encased rooftop pool, sundeck pavilion, seamless home automation, and an exclusive private elevator lobby accessed directly from stilt parking.',NULL,NULL,'/assets/images/properties/penthouse-golf-links.jpg',0,'published',13,'Golf Links Duplex Penthouse with Golf Views | Elite Homez','Premier 5 BHK duplex penthouse overlooking Delhi Golf Club with private rooftop pool and elevator.','2026-09-12 12:09:52','2026-09-12 14:55:25'),(4,4,'The Sovereign Estate Floor',NULL,'the-sovereign-estate-floor-chanakyapuri','EH-DEL-4','DLRERA2023A00892','Luxury Builder Floor','rent',1200000.00,'₹12 Lakh / month','5,500 Sq. Ft.','800 Sq. Yds.',4,4,3,'Second Floor',NULL,NULL,NULL,'Malcha Marg, Chanakyapuri, New Delhi','https://maps.google.com/?q=Malcha+Marg+Chanakyapuri+New+Delhi',NULL,'A grand residence in Delhi\'s diplomatic quarter, ideal for ambassadors, corporate leaders, and multinational executives. Spanning an entire second floor of a newly constructed freehold building, the home provides exceptional security, acoustic insulation, spacious bedrooms with ensuite dressing rooms, and refined Italian marble finishing throughout.',NULL,NULL,'/assets/images/properties/floor-chanakyapuri.jpg',0,'published',14,'Luxury Diplomatic Residence for Rent in Chanakyapuri | Elite Homez','Prestigious 4 BHK floor for lease in Chanakyapuri diplomatic enclave with top-tier security and Italian finishes.','2026-09-12 12:09:52','2026-09-12 14:55:25'),(5,5,'The Corner Manor at Panchsheel',NULL,'the-corner-manor-panchsheel-park','EH-DEL-5','DLRERA2023A00892','Park-Facing Builder Floor','sale',195000000.00,'₹19.50 Cr','4,800 Sq. Ft.','500 Sq. Yds.',4,5,3,'First Floor',NULL,NULL,NULL,'Block N, Panchsheel Park North, New Delhi','https://maps.google.com/?q=Panchsheel+Park+North+New+Delhi',NULL,'Commanding an enviable two-side open corner plot facing a lush community park, this newly completed builder floor offers unmatched natural cross-ventilation and sunlight. Includes a sprawling 45-foot living balcony, VRV air conditioning, automated ambient lighting scenes, and generous master suites with walk-in wardrobes.',NULL,NULL,'/assets/images/properties/manor-panchsheel.jpg',0,'published',15,'Park-Facing 4 BHK Floor in Panchsheel Park | Elite Homez','Prime corner 4 BHK luxury floor facing central park in Panchsheel Park North, New Delhi.','2026-09-12 12:09:52','2026-09-12 14:55:25'),(6,6,'The Orchard Residence',NULL,'the-orchard-residence-shanti-niketan','EH-DEL-6','DLRERA2023A00892','Standalone Luxury House','sale',340000000.00,'₹34.00 Cr','8,200 Sq. Ft.','700 Sq. Yds.',5,6,4,'Ground + First + Second Floors',NULL,NULL,NULL,'Shanti Niketan, New Delhi','https://maps.google.com/?q=Shanti+Niketan+New+Delhi',NULL,'Situated in quiet, wide-road Shanti Niketan, this bespoke family manor represents the height of understated luxury. Highlights include a tranquil central courtyard with water features, private elevator, staff quarters for three, rooftop entertainment pavilion, and a 4-car stilt garage.',NULL,NULL,'/assets/images/properties/residence-shanti-niketan.jpg',0,'published',16,'Bespoke Luxury Residence in Shanti Niketan | Elite Homez','5 BHK standalone luxury estate on 700 sq. yds. in Shanti Niketan with courtyard and private lift.','2026-09-12 12:09:52','2026-09-12 14:55:25'),(7,1,'Contemporary Penthouse Duplex','Block C, Diplomatic Enclave, Vasant Vihar, New Delhi','contemporary-penthouse-duplex-vasant-vihar','VV-PENT-08','DLRERA2023A00892','Ultra-Luxury Penthouse Duplex','sale',185000000.00,'₹ 18.50 Cr','4,800 sq. ft.','6,500 sq. ft. parcel apportionment',4,5,4,'Levels 03 & 04 + Private Rooftop Deck','North-East Facing · Vastu Certified','2.80m Clearance','Studio Khosla Architects · Completed 2023','Block C, Vasant Vihar, New Delhi','https://maps.google.com/?q=Vasant+Vihar+New+Delhi','28.5672° N, 77.1595° E','Commissioned by an international connoisseur and conceived by premier architectural masters, this duplex penthouse represents an uncompromising synergy of contemporary monumental architecture and residential warmth across Levels 03 and 04, culminating in an exclusive private rooftop observatory deck. Entry is orchestrated via an encrypted, high-speed biometric elevator that opens directly into a bespoke fluted travertine vestibule.\n\nThe salon spans double-height volume with monolithic Roman travertine walls imported directly from Tivoli quarries. Double-glazed acoustic glass assemblies frame verdant views of mature neem and amaltas trees, muting urban ambience while admitting soft morning eastern light. A bespoke sculptural brass lighting installation anchors the formal entertaining pavilion.\n\nA dedicated culinary laboratory featuring custom Valcucine matte quartzite casework and integrated Gaggenau appliances connects seamlessly with a discreet secondary butler’s wet kitchen, dedicated service staff quarters, and separate freight lifts. The private suite level hosts four cavernous en-suite retreats, each finished with smoked European oak parquet, custom Poliform dressers, and continuous bookmatched Statuario marble baths.','\"Curated geometry paired with raw, tactile travertine creates an acoustic stillness unique to South Delhi\'s diplomatic zone.\"','A legacy asset crafted with timeless Dholpur stone and Italian travertine, overlooking the centuries-old canopy of South Delhi.','/assets/images/stitch/area-prop-penthouse.jpg',1,'published',1,'Contemporary Penthouse Duplex | Vasant Vihar | Elite Homez','Ultra-luxury 4 BHK Penthouse Duplex in Block C, Vasant Vihar. 4,800 sq. ft., private elevator, double-height travertine salon, rooftop lap pool.','2026-09-12 14:34:32','2026-09-12 16:40:27'),(8,2,'Colonial Independent Bungalow','Prime Boulevard, Jor Bagh, New Delhi','colonial-independent-bungalow-jor-bagh','EH-JB-102','DLRERA2023A00892','Independent Heritage Bungalow','sale',410000000.00,'₹ 41.00 Cr','7,200 sq. ft.','800 sq. yds Freehold',6,7,6,'Ground + 1 Floor + Staff Courtyard','North-East Corner · Vastu Certified','3.40m Clearance','Colonial Heritage Restoration · 2022','Jor Bagh, Lutyens Perimeter, New Delhi','https://maps.google.com/?q=Jor+Bagh+New+Delhi','28.5880° N, 77.2185° E','Rare generational corner footprint nestled across lush ancient tree canopies. Featuring classical arched porticos, manicured formal lawns, separate staff quarters, and triple car courtyards.','\"A century-old arboretum setting meeting timeless Anglo-Indian architectural refinement.\"','Generational freehold title on prime Jor Bagh boulevard with uninterrupted parkland frontage.','/assets/images/stitch/jor-bagh-bungalow.jpg',1,'published',2,'Colonial Independent Bungalow | Jor Bagh | Elite Homez','Rare 800 sq. yds Freehold Colonial Bungalow in Jor Bagh. 6 Suites, expansive gardens, independent staff quarters.','2026-09-12 14:34:32','2026-09-12 14:34:32'),(9,3,'Modern Minimalist Villa with Lap Pool','The Promenade, Golf Links, New Delhi','modern-minimalist-villa-golf-links','EH-GL-218','DLRERA2023A00892','Modern Architectural Villa','sale',350000000.00,'₹ 35.00 Cr','8,200 sq. ft.','600 sq. yds Freehold',5,6,5,'Basement + Ground + 2 Floors','East Facing · Park Adjacency','3.00m Clearance','Khosla Associates · Completed 2023','Golf Links Promenade, New Delhi','https://maps.google.com/?q=Golf+Links+New+Delhi','28.5960° N, 77.2340° E','Designed by celebrated architectural modernists, this residence features a 22-meter black granite lap pool, monolithic limestone facades, floor-to-ceiling acoustic glass, and full smart-building climate integration.','\"A masterclass in restraint, privacy, and minimalist tropical design.\"','Unmatched golf course adjacency offering serene morning vistas and absolute discretion.','/assets/images/stitch/golf-links-pool-villa.jpg',1,'published',3,'Modern Minimalist Villa | Golf Links | Elite Homez','Trophy 600 sq. yds Villa in Golf Links with 22-meter black granite lap pool, 5 suites, monolithic limestone facade.','2026-09-12 14:34:32','2026-09-12 14:34:32'),(10,4,'Double-Height Travertine Residence','Diplomatic Enclave & Anand Niketan, New Delhi','double-height-travertine-residence-chanakyapuri','EH-CK-090','DLRERA2023A00892','Diplomatic Builder Floor','rent',850000.00,'₹ 8.50 L / mo','5,200 sq. ft.','1,000 sq. yds plot footprint',4,5,3,'Level 02 with Private Elevator','North Facing · Embassy Grade','3.20m Clearance','Morphogenesis · 2023','Diplomatic Crescent, Chanakyapuri, New Delhi','https://maps.google.com/?q=Chanakyapuri+New+Delhi','28.5925° N, 77.1850° E','Curated specifically for diplomatic dignitaries and corporate chiefs. Features bronze acoustic paneling, expansive travertine salon, and private landscaped courtyard garden.','\"Engineered to embassy-grade security standards with Italian marble finishes throughout.\"','Positioned within the most secure diplomatic enclave in India, surrounded by green corridors.','/assets/images/stitch/living-pavilion.jpg',0,'published',4,'Double-Height Travertine Residence | Chanakyapuri | Elite Homez','Exclusive Diplomatic Floor in Chanakyapuri. 5,200 sq. ft., 4 bedrooms, private courtyard, double-height reception.','2026-09-12 14:34:32','2026-09-12 14:34:32'),(11,6,'Cantilevered Modern Garden Estate','Westend Perimeter, Shanti Niketan, New Delhi','cantilevered-modern-garden-estate-shanti-niketan','EH-SN-510','DLRERA2023A00892','Trophy Garden Estate','sale',280000000.00,'₹ 28.00 Cr','7,500 sq. ft.','800 sq. yds Freehold',5,6,4,'Ground + 2 Floors + Reflection Pool','North-East Facing','3.10m Clearance','DDIR Architecture · 2023','Shanti Niketan, New Delhi','https://maps.google.com/?q=Shanti+Niketan+New+Delhi','28.5775° N, 77.1680° E','Dramatic cantilevered glass terraces with mature private tree canopy and an infinity reflection pool. Designed for world-class entertaining.','\"Seamless dissolution between indoor luxury salons and dense botanical gardens.\"','Quiet, leafy enclave offering sanctuary within minutes of Chanakyapuri.','/assets/images/stitch/golf-links-pool-villa.jpg',0,'published',5,'Cantilevered Modern Garden Estate | Shanti Niketan | Elite Homez','7,500 sq. ft. modern garden estate in Shanti Niketan with reflection pool, 5 bedrooms, cantilevered terraces.','2026-09-12 14:34:32','2026-09-12 14:34:32'),(12,5,'Bespoke Teak & Travertine Living Pavilion','Panchsheel Park North, New Delhi','bespoke-teak-travertine-living-pavilion-panchsheel','EH-PP-304','DLRERA2023A00892','Luxury Builder Floor','sale',142500000.00,'₹ 14.25 Cr','4,200 sq. ft.','500 sq. yds parcel share',4,5,3,'Level 01 with Private Lift & Courtyard','East Facing · Vastu Certified','3.00m Clearance','Studio Lotus · 2022','Panchsheel Park North, New Delhi','https://maps.google.com/?q=Panchsheel+Park+New+Delhi','28.5440° N, 77.2150° E','Floor-to-ceiling glazed pavilion overlooking inward zen courtyard. Finished in book-matched Italian travertine and custom plantation teak.','\"Artisanal craftsmanship where plantation teak meets monolithic Italian travertine.\"','Peaceful, secure enclave with premier club facilities and wide avenues.','/assets/images/stitch/living-pavilion.jpg',0,'published',6,'Bespoke Teak & Travertine Pavilion | Panchsheel Park | Elite Homez','4 BHK luxury floor in Panchsheel Park. 4,200 sq. ft., zen courtyard, book-matched Italian travertine.','2026-09-12 14:34:32','2026-09-12 14:34:32'),(13,1,'Travertine Courtyard Residence','Block A, Vasant Vihar Enclave, New Delhi','marble-travertine-courtyard-salon-vasant-vihar','VV-TRAV-14','DLRERA2023A00892','Diplomatic Lease Residence','rent',142500000.00,'₹ 14.25 Cr','3,900 sq. ft.','600 sq. yds footprint',4,4,2,'Level 01 Residence','North-East Facing','2.90m Clearance','Bespoke Private Commission · 2023','Block A, Vasant Vihar, New Delhi','https://maps.google.com/?q=Vasant+Vihar+New+Delhi','28.5670° N, 77.1600° E','Tailored for international ambassadors and senior consulates. Includes dual service entries, security chambers, and curated reception salon.','\"Refined diplomatic proportions with private courtyards and dedicated security chambers.\"','Diplomatic perimeter security with seamless access to embassies and airport.','/assets/images/stitch/area-prop-courtyard.jpg',0,'published',7,'Courtyard Salon Diplomatic Lease | Vasant Vihar | Elite Homez','4 BHK Diplomatic Lease in Vasant Vihar. 3,900 sq. ft., marble fireplace, private courtyard, dual service entries.','2026-09-12 14:34:32','2026-09-12 16:40:27'),(14,7,'Park-Facing Ridge Pavilion Floor','Bespoke Single-Level Residence with Expansive Balconies and Ridge Greenery Vistas','park-facing-ridge-pavilion-anand-niketan','EH-AN-0701','DLRERA2024A0091','Luxury Builder Floor','sale',245000000.00,'₹ 24.50 Cr','4,800 Sq. Ft.','500 Sq. Yards',4,5,3,'Second Floor with Private Elevator','North-East Park Facing','11\' 6\"','Morphogenesis Associate Studio','Anand Niketan, South Delhi',NULL,'28.5772° N, 77.1652° E','A masterfully curated 4-bedroom single-level residence situated along a quiet inner avenue of Anand Niketan. Features direct park views, imported Greek Thassos marble, concealed VRV air conditioning, and private elevator access directly into the residence.',NULL,NULL,'/assets/images/areas/anand-niketan.jpg',1,'published',14,'Park-Facing Luxury Floor in A